with with_prev as (select *, lag(txn_time) over (partition by txn_type order by txn_time, id) as prev_txn_time from transactions), flagged as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval '14' day then 1 else 0 end as new_group_flag from with_prev), islands as (select *, sum(new_group_flag) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as burst_id from flagged) select case when new_group_flag >= 1 then 'PREMIUM' else 'STANDARD' end as new_group_flag_tier, merchant, burst_id, count(distinct merchant) as distinct_merchants, percentile_approx(amount, array(0.25, 0.5, 0.75)) as amount_quartiles, count(distinct account_id) as distinct_account_ids from islands group by case when new_group_flag >= 1 then 'PREMIUM' else 'STANDARD' end, merchant, burst_id having count(distinct merchant) >= 1 order by distinct_merchants desc nulls first;
